using Microsoft.EntityFrameworkCore;using OrderFlow.Notifications.Application.Abstractions.Persistence;using OrderFlow.Notifications.Domain.Notifications;namespace OrderFlow.Notifications.Infrastructure.Persistence;public sealed class NotificationRepository(NotificationsDbContext db):INotificationRepository{public Task<Notification?> GetAsync(Guid id,CancellationToken ct)=>db.Notifications.Include(x=>x.Attempts).SingleOrDefaultAsync(x=>x.Id==id,ct);public async Task<IReadOnlyList<Notification>> GetForRecipientAsync(string recipient,CancellationToken ct)=>await db.Notifications.AsNoTracking().Include(x=>x.Attempts).Where(x=>x.Recipient==recipient).OrderByDescending(x=>x.CreatedAt).ToListAsync(ct);public async Task AddAsync(Notification x,CancellationToken ct){db.Notifications.Add(x);await db.SaveChangesAsync(ct);}public async Task SaveAsync(CancellationToken ct)=>await db.SaveChangesAsync(ct);}
